def parse_kv(text):
    """Parse 'a=1;b=2' into {'a': 1, 'b': 2}. Values are integers. Empty segments and spaces around keys and values are ignored."""
    out = {}
    for part in text.split(';'):
        if not part.strip():
            continue
        key, value = part.split('=', 1)
        out[key.strip()] = int(value.strip())
    return out

