_TABLE = [(1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'), (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'), (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')]


def _to_roman(n):
    out = ''
    for v, sym in _TABLE:
        while n >= v:
            out += sym
            n -= v
    return out


_CANON = {_to_roman(n): n for n in range(1, 4000)}


def from_roman(s):
    if not isinstance(s, str) or s not in _CANON:
        raise ValueError(s)
    return _CANON[s]
